    ```
  - [x] `seed-b-backend.Api/Controllers/Dtos/ProductDetailDto.cs` (NEU):
    ```csharp
    namespace seed_b_backend.Api.Controllers.Dtos;

    public class ProductDetailDto
    {
        public required string Id { get; set; }
        public required string Name { get; set; }
        public required string Description { get; set; }
        public required CategoryRefDto Category { get; set; }
        public required SubcategoryRefDto Subcategory { get; set; }
        public required IReadOnlyList<ProductPropertyDto> Properties { get; set; }
        public double? AverageRating { get; set; }
        public required int RatingCount { get; set; }
        public required IReadOnlyList<SupplierOfferDto> Offers { get; set; }
    }
    ```
  - [x] `seed-b-backend.Api/Controllers/ProductsController.cs`: neue Action `GetProduct` ergänzen (nach `GetProducts`, gleicher Controller — `api/products` bleibt Basis-Route):
    ```csharp
    [HttpGet("{id}")]
    public async Task<ActionResult<ProductDetailDto>> GetProduct(string id, CancellationToken ct = default)
    {
        var detail = await catalogService.GetProductDetailAsync(id, ct);
        if (detail is null)
        {
            return NotFound();
        }

        var product = detail.Product;
        var response = new ProductDetailDto
        {
            Id = product.Id,
            Name = product.Name,
            Description = product.Description,
            Category = new CategoryRefDto { Id = product.Subcategory!.Category!.Id, Name = product.Subcategory.Category.Name },
            Subcategory = new SubcategoryRefDto { Id = product.Subcategory.Id, Name = product.Subcategory.Name },
            Properties = product.PropertyValues
                .OrderBy(pv => pv.Name, StringComparer.Ordinal)
                .Select(pv => new ProductPropertyDto { Name = pv.Name, Value = pv.Value })
                .ToList(),
            AverageRating = detail.AverageRating,
            RatingCount = detail.RatingCount,
            Offers = product.Offers
                .OrderBy(o => o.Price)
                .ThenBy(o => o.SupplierId, StringComparer.Ordinal)
                .Select(o => new SupplierOfferDto { SupplierId = o.SupplierId, SupplierName = o.Supplier!.Name, Price = o.Price })
                .ToList()
        };

        return Ok(response);
    }
    ```
    - **`[HttpGet("{id}")]` neben dem bestehenden `[HttpGet]` (ohne Template) auf derselben `[Route("api/products")]`-Basis:** ASP.NET Core unterscheidet beide Routen eindeutig (`GET /api/products` → Liste, `GET /api/products/{id}` → Detail), kein Routing-Konflikt, kein neuer Controller nötig — konsistent mit der Architektur-Vorgabe „FR-7 (product detail) | `CatalogService` + `ProductsController`" (Capability → Architecture Map).
    - **Sortierung der Lieferanten `OrderBy(o => o.Price).ThenBy(o => o.SupplierId, StringComparer.Ordinal)`:** AC 2 verlangt aufsteigend nach Preis; `ThenBy(SupplierId)` ist ein deterministischer Tie-Break bei gleichem Preis (identisches Prinzip wie die bereits bestehenden `.ThenBy(p => p.Id)`-Tie-Breaks in `GetProductsAsync`), verhindert flackernde Reihenfolge zwischen Requests.
    - **Sortierung der Eigenschaften `OrderBy(pv => pv.Name, StringComparer.Ordinal)`:** identisches Muster wie die bereits in Story 1.6 etablierte alphabetische, kulturunabhängige Sortierung der Eigenschaftsnamen.
    - **404 statt Exception bei unbekannter ID (AC 6):** `NotFound()` liefert einen leeren `404`-Body ohne Sonderformat — ausreichend, da AC 6 nur „Nicht-gefunden-Zustand statt Fehler" verlangt, kein strukturiertes Fehlerformat wie bei FR14 (AD-3) vorschreibt.

- [x] **Task 4: Backend-Tests (xUnit v3)** (AC: 1, 2, 3, 4, 6)
  - [x] `seed-b-backend.Tests/Application/CatalogServiceTests.cs`: neue private Hilfsmethode `SeedProductDetailData()` (Kategorie/Unterkategorie mit Eigenschaften, ein Produkt, zwei Lieferanten mit unterschiedlichem Preis) — Muster analog `SeedPropertyFilterProducts()`:
    ```csharp
    private void SeedProductDetailData()
    {
        var category = new Category { Id = "CD", Name = "Detailkategorie" };
        var subcategory = new Subcategory { Id = "SD1", Name = "Detailunterkategorie", CategoryId = "CD" };
        _context.Categories.Add(category);
        _context.Subcategories.Add(subcategory);

        var product = new Product { Id = "PD1", Name = "Detailprodukt", Description = "Eine Beschreibung", SubcategoryId = "SD1" };
        _context.Products.Add(product);
        _context.ProductPropertyValues.AddRange(
            new ProductPropertyValue { ProductId = "PD1", Name = "Farbe", Value = "Rot" },
            new ProductPropertyValue { ProductId = "PD1", Name = "Bauform", Value = "Kompakt" }
        );

        _context.Suppliers.AddRange(
            new Supplier { Id = "LD1", Name = "Lieferant Teuer" },
            new Supplier { Id = "LD2", Name = "Lieferant Günstig" }
        );
        _context.Offers.AddRange(
            new Offer { ProductId = "PD1", SupplierId = "LD1", Price = 29.99m },
            new Offer { ProductId = "PD1", SupplierId = "LD2", Price = 19.99m }
        );

        _context.SaveChanges();
    }
    ```
  - [x] Test `GetProductDetailAsync_ReturnsNameDescriptionCategoryAndProperties`: `GetProductDetailAsync("PD1")` → `Product.Name == "Detailprodukt"`, `Product.Description == "Eine Beschreibung"`, `Product.Subcategory!.Id == "SD1"`, `Product.Subcategory.Category!.Id == "CD"`, `Product.PropertyValues.Count == 2` (AC 1)
  - [x] Test `GetProductDetailAsync_OffersAreOrderedAscendingByPrice`: `GetProductDetailAsync("PD1")` → `result!.Product.Offers.OrderBy(o => o.Price).Select(o => o.SupplierId)` beginnt mit `"LD2"` (19.99) vor `"LD1"` (29.99) — Test prüft explizit die Rohdaten und dokumentiert, dass die eigentliche Sortier-Assertion auf DTO-Ebene erfolgt, da `CatalogService` die `Offers`-Sortierung selbst nicht vornimmt (das übernimmt der Controller); ergänzend ein zweiter Test auf Controller-Ebene ist nicht vorgesehen (kein bestehendes Controller-Testmuster im Projekt, siehe `deferred-work.md` Story 1.5) (AC 2)
  - [x] Test `GetProductDetailAsync_NoRatings_ReturnsNullAverageAndZeroCount`: `SeedProductDetailData()` ohne `Rating`-Zeilen, `GetProductDetailAsync("PD1")` → `result!.AverageRating` ist `null`, `result.RatingCount == 0` (AC 3)
  - [x] Test `GetProductDetailAsync_WithRatings_ReturnsAverageAndCount`: zusätzlich `_context.Ratings.AddRange(new Rating { ProductId = "PD1", AuthorName = "Anna", Score = 4 }, new Rating { ProductId = "PD1", AuthorName = "Ben", Score = 2 })` vor `GetProductDetailAsync("PD1")` → `result!.AverageRating == 3.0`, `result.RatingCount == 2` (AC 4)
  - [x] Test `GetProductDetailAsync_UnknownId_ReturnsNull`: `GetProductDetailAsync("NICHT-VORHANDEN")` → `Assert.Null(result)` (AC 6)
  - [x] `seed-b-backend.Tests/Data/RatingConfigurationTests.cs` (NEU) — verifiziert AD-5s Unique-Constraint auf DB-Ebene, unabhängig von der (erst in Story 2.3 gebauten) Anwendungslogik, gleiches SQLite-In-Memory-Testmuster wie `CatalogServiceTests`:
    ```csharp
    using Microsoft.Data.Sqlite;
    using Microsoft.EntityFrameworkCore;
    using seed_b_backend.Api.Data;
    using seed_b_backend.Api.Domain;

    namespace seed_b_backend.Tests.Data;

    public class RatingConfigurationTests : IDisposable
    {
        private readonly SqliteConnection _connection;
        private readonly AppDbContext _context;

        public RatingConfigurationTests()
        {
            _connection = new SqliteConnection("Data Source=:memory:");
            _connection.Open();

            var options = new DbContextOptionsBuilder<AppDbContext>()
                .UseSqlite(_connection)
                .Options;

            _context = new AppDbContext(options);
            _context.Database.EnsureCreated();

            _context.Categories.Add(new Category { Id = "CR", Name = "Ratingkategorie" });
            _context.Subcategories.Add(new Subcategory { Id = "SR1", Name = "Ratingunterkategorie", CategoryId = "CR" });
            _context.Products.Add(new Product { Id = "PR1", Name = "Ratingprodukt", Description = "Beschreibung", SubcategoryId = "SR1" });
            _context.SaveChanges();
        }

        public void Dispose()
        {
            _context.Dispose();
            _connection.Dispose();
        }

        [Fact]
        public void SavingSecondRatingWithSameProductAndAuthor_ThrowsOnPrimaryKeyViolation()
        {
            _context.Ratings.Add(new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 5 });
            _context.SaveChanges();

            _context.Ratings.Add(new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 1 });

            Assert.Throws<DbUpdateException>(() => _context.SaveChanges());
        }

        [Fact]
        public void SavingRatingsWithDifferentAuthorsForSameProduct_Succeeds()
        {
            _context.Ratings.AddRange(
                new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 5 },
                new Rating { ProductId = "PR1", AuthorName = "Ben", Score = 3 }
            );

            _context.SaveChanges();

