451	+    private readonly SqliteConnection _connection;
452	+    private readonly AppDbContext _context;
453	+
454	+    public RatingConfigurationTests()
455	+    {
456	+        _connection = new SqliteConnection("Data Source=:memory:");
457	+        _connection.Open();
458	+
459	+        var options = new DbContextOptionsBuilder<AppDbContext>()
460	+            .UseSqlite(_connection)
461	+            .Options;
462	+
463	+        _context = new AppDbContext(options);
464	+        _context.Database.EnsureCreated();
465	+
466	+        _context.Categories.Add(new Category { Id = "CR", Name = "Ratingkategorie" });
467	+        _context.Subcategories.Add(new Subcategory { Id = "SR1", Name = "Ratingunterkategorie", CategoryId = "CR" });
468	+        _context.Products.Add(new Product { Id = "PR1", Name = "Ratingprodukt", Description = "Beschreibung", SubcategoryId = "SR1" });
469	+        _context.SaveChanges();
470	+    }
471	+
472	+    public void Dispose()
473	+    {
474	+        _context.Dispose();
475	+        _connection.Dispose();
476	+    }
477	+
478	+    [Fact]
479	+    public void SavingSecondRatingWithSameProductAndAuthor_ThrowsOnPrimaryKeyViolation()
480	+    {
481	+        _context.Ratings.Add(new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 5 });
482	+        _context.SaveChanges();
483	+
484	+        // Zweiter Insert über eine eigene DbContext-Instanz (gleiche Connection): so greift
485	+        // tatsächlich der DB-Constraint statt nur EF Cores In-Memory-Change-Tracker, der einen
486	+        // Duplikat-Key im selben Context bereits vor dem SaveChanges als InvalidOperationException
487	+        // ablehnen würde.
488	+        var options = new DbContextOptionsBuilder<AppDbContext>()
489	+            .UseSqlite(_connection)
490	+            .Options;
491	+        using var secondContext = new AppDbContext(options);
492	+        secondContext.Ratings.Add(new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 1 });
493	+
494	+        Assert.Throws<DbUpdateException>(() => secondContext.SaveChanges());
495	+    }
496	+
497	+    [Fact]
498	+    public void SavingRatingsWithDifferentAuthorsForSameProduct_Succeeds()
499	+    {
500	+        _context.Ratings.AddRange(
501	+            new Rating { ProductId = "PR1", AuthorName = "Anna", Score = 5 },
502	+            new Rating { ProductId = "PR1", AuthorName = "Ben", Score = 3 }
503	+        );
504	+
505	+        _context.SaveChanges();
506	+
507	+        Assert.Equal(2, _context.Ratings.Count());
508	+    }
509	+}
