452	+    private readonly AppDbContext _context;
453	+
454	+    public RatingConfigurationTests()
455	+    {
456	+        _connection = new SqliteConnection("Data Source=:memory:");
457	+        _connection.Open();
458	+
459	+        var options = new DbContextOptionsBuilder<AppDbContext>()
460	+            .UseSqlite(_connection)
461	+            .Options;
462	+
463	+        _context = new AppDbContext(options);
464	+        _context.Database.EnsureCreated();
465	+
466	+        _context.Categories.Add(new Category { Id = "CR", Name = "Ratingkategorie" });
467	+        _context.Subcategories.Add(new Subcategory { Id = "SR1", Name = "Ratingunterkategorie", CategoryId = "CR" });
468	+        _context.Products.Add(new Product { Id = "PR1", Name = "Ratingprodukt", Description = "Beschreibung", SubcategoryId = "SR1" });
469	+        _context.SaveChanges();
